import{_ as s,a0 as r,w as l,s as p,ao as u,I as a,x as e,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux有问必答：如何检查Linux系统的最后重启时间 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何检查Linux系统的最后重启时间 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何检查Linux系统的最后重启时间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何检查Linux系统的最后重启时间 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140811 Linux FAQs with Answers--How to check the last time system was rebooted on Linux","title":"Linux有问必答：如何检查Linux系统的最后重启时间","tag":"201409","desc":""},"relativePath":"201409/20140811 Linux FAQs with Answers--How to check the last time system was rebooted on Linux.md","filePath":"[post].md"}'),m={name:"201409/20140811 Linux FAQs with Answers--How to check the last time system was rebooted on Linux.md"};function d(x,t,h,L,f,_){const o=r("Link");return l(),p("div",null,[t[11]||(t[11]=u(`<h1 id="linux有问必答-如何检查linux系统的最后重启时间" tabindex="-1">Linux有问必答：如何检查Linux系统的最后重启时间 <a class="header-anchor" href="#linux有问必答-如何检查linux系统的最后重启时间" aria-label="Permalink to “Linux有问必答：如何检查Linux系统的最后重启时间”">​</a></h1><blockquote><p><strong>问题</strong>: 是否有一个命令可以快速地检查系统已经运行了多久? 也就是我怎么知道Linux系统最后的重启时间?</p></blockquote><p>有许多方法来查询系统最后的重启时间。</p><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><p>第一种方法是使用last命令</p><pre><code>$ last reboot 
</code></pre><p><img src="https://farm4.staticflickr.com/3925/14881994335_041e9c2f86_z.jpg" alt=""></p><p>这条命令实际上显示的是最近几天的系统运行时间。last原本被设计来显示某个特定用户的登录历史。在Linux中，有一个特别的“伪用户”称为reboot会在系统重启的时候立即自动登录。这样通过检查reboot用户的登录历史，你就可以检查最后的重启时间。</p><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h3><p>另外一个检测系统最后启动时间的方法是使用who命令带上‘-b’选项。</p><pre><code>$ who -b 
</code></pre><h3 id="方法三" tabindex="-1">方法三 <a class="header-anchor" href="#方法三" aria-label="Permalink to “方法三”">​</a></h3><p>你同样可以使用uptime命令来推断系统最后的启动时间。uptime命令会显示当前的时间，同样也会显示系统已经运行的时间。从这些信息中，你就可以计算系统最后启动的时间了</p><pre><code>$ uptime 
</code></pre><p><img src="https://farm4.staticflickr.com/3915/14881660192_58f2843969_o.png" alt=""></p><hr>`,16)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),i(o,{href:"http://ask.xmodulo.com/check-last-time-system-rebooted-linux.html"},{default:n(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/check-last-time-system-rebooted-linux.html",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("译者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),i(o,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),i(o,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const k=s(m,[["render",d]]);export{T as __pageData,k as default};
